using System;
using System.Collections.Generic;
using Cypher.Core;
using UnityEngine;

namespace Cypher.City
{
    /// <summary>
    /// Builds the textured material instances the city renders with: window atlas on the walls, wet
    /// asphalt on the road, paving on the sidewalks, concrete on walls and roofs. The textures are
    /// generated by Cypher.Core at startup (the prototype ships no art assets); the project's material
    /// assets are never modified, each surface gets an instance.
    /// </summary>
    public static class SurfaceMaterials
    {
        public const int AsphaltSize = 512;
        public const int PavingSize = 512;
        public const int ConcreteSize = 512;
        public const int WetRoughnessSize = 512;
        public const int ConcreteRoughnessSize = 256;

        // The prototype tiles the asphalt 46x and its roughness map 9x across the roadbed, so the
        // roughness repeats every 46/9 asphalt tiles. The road mesh UVs already carry the 46.
        public const float RoadMaskTiling = 9f / 46f;

        // The prototype shares the 9x wet roughness map with the sidewalks, which at 3 m per paving tile
        // makes puddle patches a few centimetres wide. A 24 m tile makes them metres wide instead.
        public const float SidewalkMaskTiling = 3f / 24f;

        // Concrete UVs are in metres / 4.5 on both the walls and the roofs.
        public const float ConcreteTiling = (float)(1.0 / MeshBuilder.ConcreteUvScale);

        // Base roughness multipliers from the prototype's materials, baked into the smoothness maps.
        // The road is the exception: the prototype uses 1.0 because its reflections are screen-space and stay
        // sharp. A reflection probe blurs by roughness, so the same map would smear every sign away; scaling
        // the roughness down keeps the prototype's puddle pattern but leaves the whole road glossy enough to
        // show neon.
        const double RoadRoughness = 0.5;
        const double SidewalkRoughness = 0.9;
        const double ConcreteRoughness = 0.94;

        static readonly int BaseMap = Shader.PropertyToID("_BaseMap");
        static readonly int MaskMap = Shader.PropertyToID("_MaskMap");
        static readonly int EmissionMap = Shader.PropertyToID("_EmissionMap");
        static readonly int WorldUV = Shader.PropertyToID("_WorldUV");

        /// <summary>Instances of the given materials with generated textures. Everything created is added to owned.</summary>
        public static CityMaterials Create(CityMaterials assets, int atlasSize, ICollection<UnityEngine.Object> owned)
        {
            if (!assets.IsComplete) throw new ArgumentException("all seven city materials are required", nameof(assets));
            if (owned == null) throw new ArgumentNullException(nameof(owned));

            byte[] wetRoughness = SurfaceTextures.WetRoughness(WetRoughnessSize);
            Texture2D atlas = Own(owned, MakeTexture("WindowAtlas", WindowAtlas.Generate(atlasSize), atlasSize, srgb: true, aniso: 4));
            Texture2D concrete = Own(owned, MakeTexture("Concrete", SurfaceTextures.Concrete(ConcreteSize), ConcreteSize, srgb: true, aniso: 4));
            Texture2D concreteSmooth = Own(owned, MakeTexture("ConcreteSmoothness",
                SurfaceTextures.SmoothnessFromRoughness(SurfaceTextures.ConcreteRoughness(ConcreteRoughnessSize), ConcreteRoughness),
                ConcreteRoughnessSize, srgb: false, aniso: 4));

            Material walls = Instance(assets.Walls, owned);
            walls.SetTexture(EmissionMap, atlas);
            ConfigureConcrete(walls, concrete, concreteSmooth);

            Material roofs = Instance(assets.Roofs, owned);
            ConfigureConcrete(roofs, concrete, concreteSmooth);

            Material road = Instance(assets.Road, owned);
            road.SetTexture(BaseMap, Own(owned, MakeTexture("Asphalt", SurfaceTextures.Asphalt(AsphaltSize), AsphaltSize, srgb: true, aniso: 8)));
            road.SetTexture(MaskMap, Own(owned, MakeTexture("RoadSmoothness",
                SurfaceTextures.SmoothnessFromRoughness(wetRoughness, RoadRoughness), WetRoughnessSize, srgb: false, aniso: 8)));
            road.SetTextureScale(MaskMap, new Vector2(RoadMaskTiling, RoadMaskTiling));

            Material sidewalk = Instance(assets.Sidewalk, owned);
            sidewalk.SetTexture(BaseMap, Own(owned, MakeTexture("Paving", SurfaceTextures.Paving(PavingSize), PavingSize, srgb: true, aniso: 8)));
            sidewalk.SetTexture(MaskMap, Own(owned, MakeTexture("SidewalkSmoothness",
                SurfaceTextures.SmoothnessFromRoughness(wetRoughness, SidewalkRoughness), WetRoughnessSize, srgb: false, aniso: 4)));
            sidewalk.SetTextureScale(MaskMap, new Vector2(SidewalkMaskTiling, SidewalkMaskTiling));

            // Paint, metal and neon take no generated textures, so the project's own materials are used as they are.
            return new CityMaterials { Walls = walls, Roofs = roofs, Sidewalk = sidewalk, Road = road, Paint = assets.Paint, Metal = assets.Metal, Neon = assets.Neon };
        }

        static void ConfigureConcrete(Material material, Texture2D albedo, Texture2D smoothness)
        {
            material.SetFloat(WorldUV, 1f);
            material.SetTexture(BaseMap, albedo);
            material.SetTexture(MaskMap, smoothness);
            material.SetTextureScale(BaseMap, new Vector2(ConcreteTiling, ConcreteTiling));
            material.SetTextureScale(MaskMap, new Vector2(ConcreteTiling, ConcreteTiling));
        }

        static Material Instance(Material source, ICollection<UnityEngine.Object> owned)
        {
            var m = new Material(source) { name = source.name + " (instance)" };
            owned.Add(m);
            return m;
        }

        static T Own<T>(ICollection<UnityEngine.Object> owned, T o) where T : UnityEngine.Object
        {
            owned.Add(o);
            return o;
        }

        /// <summary>RGBA32 texture from raw bytes with a full mip chain, trilinear and repeating.</summary>
        public static Texture2D MakeTexture(string name, byte[] rgba, int size, bool srgb, int aniso)
        {
            if (rgba == null) throw new ArgumentNullException(nameof(rgba));
            if (rgba.Length != size * size * 4) throw new ArgumentException($"{name}: {rgba.Length} bytes is not a {size}x{size} RGBA image", nameof(rgba));

            var texture = new Texture2D(size, size, TextureFormat.RGBA32, true, !srgb)
            {
                name = name,
                wrapMode = TextureWrapMode.Repeat,
                filterMode = FilterMode.Trilinear,
                anisoLevel = aniso,
            };
            texture.SetPixelData(rgba, 0);   // base level only; Apply generates the mip chain
            texture.Apply(true, true);
            return texture;
        }
    }
}
